import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 17 A man-made disease","description":"学习 cause、lead to 与 be associated with，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 17 A man-made disease","description":"学习 cause、lead to 与 be associated with，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 cause、lead to 与 be associated with，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 16 The modern city","link":"/life/english/new-concept/book-4/unit-02/lesson-016"},"next":{"text":"第四册：流利英语 · Lesson 18 Porpoises","link":"/life/english/new-concept/book-4/unit-03/lesson-018"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 16 The modern city","link":"/life/english/new-concept/book-4/unit-02/lesson-016"},"next":{"text":"第四册：流利英语 · Lesson 18 Porpoises","link":"/life/english/new-concept/book-4/unit-03/lesson-018"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-017.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-017.md"}'),o={name:"life/english/new-concept/book-4/unit-03/lesson-017.md"};function s(l,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-17-a-man-made-disease" tabindex="-1">第四册：流利英语 · Lesson 17 A man-made disease <a class="header-anchor" href="#第四册-流利英语-·-lesson-17-a-man-made-disease" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 17 A man-made disease&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以兔子引入、种群扩张与人为疾病干预的历史叙述为入口，阅读人类改变生态系统后出现的连锁后果。训练把原定目标与实际影响分开，并区分相关与因果。本课不把历史干预当作现代操作建议，而是用原创观察情境练习说明证据、替代解释和结论范围。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>population</td><td>/ˌpɒpjəˈleɪʃən/</td><td>n.</td><td>种群</td><td>a rabbit population</td></tr><tr><td>intervention</td><td>/ˌɪntəˈvenʃən/</td><td>n.</td><td>干预</td><td>an ecological intervention</td></tr><tr><td>spread</td><td>/spred/</td><td>v.</td><td>传播；扩展</td><td>spread beyond an area</td></tr><tr><td>consequence</td><td>/ˈkɒnsɪkwəns/</td><td>n.</td><td>后果</td><td>an unintended consequence</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be associated with — 与某现象相关</li><li>account for — 解释；占某比例</li></ul><h2 id="语法讲解-cause、lead-to-与-be-associated-with" tabindex="-1">语法讲解：cause、lead to 与 be associated with <a class="header-anchor" href="#语法讲解-cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;语法讲解：cause、lead to 与 be associated with&quot;">​</a></h2><p>cause + 宾语表示造成结果，lead to 后接名词或动名词表示导致；be associated with 只表示存在关联，证据强度不同。A change was associated with fewer rabbits 与 A change caused the decline 不是同义改写。lead to 中的 to 是介词，因此接 doing 而非动词原形。生态叙述还应检查气候、食物和调查方法等变量，不能因为作者使用 cause 就认为因果已经得到充分证明。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p></blockquote><p>在这项虚构调查中，更潮湿的春季与田地附近较少的兔子相关。</p><p>was associated with 只说明关联；In the fictional survey 限定为练习数据，未确认兔子减少的原因。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把 associated with 在摘要中升级为 caused；这改变了证据含义。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 associated with 时保持词组连贯；重读 near the field，并回听地点限制是否清楚，避免把局部观察读成普遍结论。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A wetter spring was associated with fewer rabbits near the field. Changes in food supply may also explain the difference. A better survey would compare several sites over more than one season.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为虚构兔子数量调查写三句摘要：一项关联、另一种解释、后续观察需要。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用关联、替代解释和跨地点观察构成谨慎摘要，不据历史疾病故事提供干预步骤。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是否已经证明更潮湿的春季导致兔子减少？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> be associated with 表关联，还需要排除其他解释。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The new barrier led to ___ the animals away from the road.（keep）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> keeping</p><p><strong>解析：</strong> lead to 的 to 是介词，后接动名词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>虚构调查中，兔子数量较少的地点在哪里？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> near the field，田地附近。</p><p><strong>解析：</strong> 介词短语限定观察地点，不能外推到全部地区。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：cause、lead to 与 be associated with。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-018">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",s]]);export{u as __pageData,b as default};
